package com.company.platform.integration.application;
import com.company.platform.integration.domain.Connector;import com.company.platform.integration.framework.*;import com.company.platform.integration.infrastructure.TenantContextProvider;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SynchronizationEngine{private final JdbcTemplate jdbc;private final TenantContextProvider tenant;private final AdapterRegistry adapters;private final PayloadTransformer transformer;private final IntegrationPlatformService platform;public SynchronizationEngine(JdbcTemplate j,TenantContextProvider t,AdapterRegistry a,PayloadTransformer p,IntegrationPlatformService s){jdbc=j;tenant=t;adapters=a;transformer=p;platform=s;}@Transactional public Map<String,Object> synchronize(UUID connectorId,String executionType,Object payload){Connector c=platform.get(connectorId);if(!"ACTIVE".equals(c.status()))throw new IllegalStateException("connector is not active");UUID sync=UUID.randomUUID(),corr=UUID.randomUUID();Instant started=Instant.now();AdapterContext ctx=new AdapterContext(tenant.currentTenantId(),c.id(),corr,c.provider(),c.version());Object transformed=transformer.transform(payload,"generic",c.version());if("INBOUND".equalsIgnoreCase(c.direction()))adapters.inbound(c.provider()).receive(ctx,transformed);else adapters.outbound(c.provider()).send(ctx,transformed);long ms=Duration.between(started,Instant.now()).toMillis();jdbc.update("INSERT INTO integration_synchronizations(id,tenant_id,connector_id,provider,status,execution_type,execution_time_ms,records_processed,records_succeeded,records_failed,correlation_id,created_at,finished_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",sync,tenant.currentTenantId(),c.id(),c.provider(),"COMPLETED",executionType,ms,1,1,0,corr,Timestamp.from(started),Timestamp.from(Instant.now()));return Map.of("synchronizationId",sync,"connectorId",c.id(),"tenantId",tenant.currentTenantId(),"provider",c.provider(),"recordsProcessed",1,"recordsSucceeded",1,"correlationId",corr,"executionTimeMs",ms);}}
